function load(p) { return Vbo.loadVboText(fs.readFileSync(p, "utf8")); }
const rd = load("dump/CLR_F296_#5204_SIC TEST0003.vbo");
const latI = Analyze.colIndex(rd, ["lat", "latitude"]);
const longI = Analyze.colIndex(rd, ["long", "longitude"]);
const origin = [rd.cols[rd.names[longI]][0], rd.cols[rd.names[latI]][0]];
const G = 9.81;
const laps = Analyze.identifyLaps(rd).filter(l => l.complete);
const tr = Analyze.buildTrack(rd, laps[2], origin);
const det = Analyze.detectCorners(tr);

// For each detected region, find internal |latAcc| local maxima (raw, unsmoothed used in analysis)
// that are "genuine" sub-turn apexes: separated by >=15 m and >=0.9 g, within the region span.
function idxAt(d){let lo=0,hi=tr.count-1;while(lo<hi){const m=(lo+hi)>>1;if(tr.dist[m]<d)lo=m+1;else hi=m;}return lo;}
function subApexes(r){
  const a=idxAt(r.startD), b=idxAt(r.endD);
  const pts=[];
  for(let i=a+1;i<b;i++){
    const m=Math.abs(tr.latAcc[i]);
    if(m>=Math.abs(tr.latAcc[i-1])&&m>=Math.abs(tr.latAcc[i+1])&&m>0.9*G){
      pts.push({d:tr.dist[i],g:m/G});
    }
  }
  // dedupe: keep peaks separated by >15m
  const out=[];
  for(const p of pts){ if(!out.length||p.d-out[out.length-1].d>15) out.push(p); }
  return out;
}
console.log("Region -> internal sub-apexes (candidate official sub-turns):");
det.forEach((c,i)=>{
  const sub=subApexes(c);
  console.log("  r"+(i+1)+" "+c.dir+" apex="+c.apexD.toFixed(0)+" ["+c.startD.toFixed(0)+"-"+c.endD.toFixed(0)+"] len="+(c.endD-c.startD).toFixed(0)+"m -> "+
    (sub.length? sub.map(s=>s.d.toFixed(0)+"m@"+s.g.toFixed(2)+"g").join(" | ") : "(single sweep, no clear sub-apex)"));
});
