{"content":"const fs = require("fs");
const path = require("path");
global.window = global;
const Vbo = require(path.join(__dirname, "vbo.js"));
const Analyze = require(path.join(__dirname, "analyze.js"));
function load(p) { return Vbo.loadVboText(fs.readFileSync(p, "utf8")); }
const rd = load("dump/CLR_F296_#5204_SIC TEST0003.vbo");
const latI = Analyze.colIndex(rd, ["lat", "latitude"]);
const longI = Analyze.colIndex(rd, ["long", "longitude"]);
const origin = [rd.cols[rd.names[longI]][0], rd.cols[rd.names[latI]][0]];
const G = 9.81;
const laps = Analyze.identifyLaps(rd).filter(l => l.complete);
const tr = Analyze.buildTrack(rd, laps[2], origin);
const L = tr.length;
const det = Analyze.detectCorners(tr);

// Nearest-official-turn labeling: we know official turn POSITIONS as fractions of lap.
// Derive the fractions from the data by anchoring known landmarks. For Shanghai:
//   - T13 = region ending ~3366 (start of 1.17km straight), T14 = region @4531 (after straight)
//   - T16 = last region @4891, then 382m to line = pit straight.
// We fit a per-turn fraction table so a detected region snaps to the nearest official turn.
const OFFICIAL = [
  {n:1,  name:"Turn 1",       dir:"R"},
  {n:2,  name:"Turn 2",       dir:"R"},
  {n:3,  name:"Turn 3 hairpin",dir:"R"},
  {n:4,  name:"Turn 4",       dir:"R"},
  {n:5,  name:"Turn 5",       dir:"L"},
  {n:6,  name:"Turn 6 hairpin",dir:"R"},
  {n:7,  name:"Turn 7",       dir:"L"},
  {n:8,  name:"Turn 8",       dir:"R"},
  {n:9,  name:"Turn 9",       dir:"L"},
  {n:10, name:"Turn 10",      dir:"L"},
  {n:11, name:"Turn 11",      dir:"L"},
  {n:12, name:"Turn 12",      dir:"R"},
  {n:13, name:"Turn 13 long R",dir:"R"},
  {n:14, name:"Turn 14 hairpin",dir:"R"},
  {n:15, name:"Turn 15",      dir:"R"},
  {n:16, name:"Turn 16 last L",dir:"L"}
];

// Position estimate per detected region as a fraction of the lap. We need to assign
// an official turn number to each detected region by ORDER, then the region's apex
// fraction becomes that turn's best position estimate. Then unturns not seen get
// interpolated between neighbours.
// First produce the detected-region sequence, then assign official turn indices by
// walking official turns so each region takes the earliest still-open official turn
// whose direction matches, else the turn just after the previous assignment.
function assign(official, regions) {
  const res = [];    // per official turn: {o, regionApexD or null}
  // Build a mapping region_idx -> set of official turns. Greedy order-preserving:
  let ri = 0, lastUsedOfficial = -1;
  for (let oi = 0; oi < official.length; oi++) {
    const o = official[oi];
    if (ri < regions.length) {
      const r = regions[ri];
      // accept this region for this turn if its direction matches, or if it's the
      // very next unmatched region (to keep order), but only one region per turn.
      res.push({ o, r: r });
      // advance if the NEXT region has a different direction than the current turn,
      // meaning current region is a single-turn sweep.
      const next = regions[ri + 1];
      if (!next || next.dir !== o.d) ri++;
    } else {
      res.push({ o, r: null });
    }
  }
  return res;
}
const mapped = assign(OFFICIAL, det);
console.log("Official turn | snapped region apex (m) | region dir | lap frac");
mapped.forEach(m => {
  const r = m.r;
  const frac = r ? (r.apexD / L) : null;
  console.log("  T" + String(m.o.n).padStart(2) + " " + m.o.dir + " | " +
    (r ? String(r.apexD.toFixed(0)).padStart(5) : "   ---") + " | " +
    (r ? r.dir : "--") + " | " + (frac ? frac.toFixed(3) : "--"));
});
