{"content":"const fs = require("fs");
const path = require("path");
global.window = global;
const Vbo = require(path.join(__dirname, "vbo.js"));
const Analyze = require(path.join(__dirname, "analyze.js"));
function load(p) { return Vbo.loadVboText(fs.readFileSync(p, "utf8")); }
const rd = load("dump/CLR_F296_#5204_SIC TEST0003.vbo");
const latI = Analyze.colIndex(rd, ["lat", "latitude"]);
const longI = Analyze.colIndex(rd, ["long", "longitude"]);
const origin = [rd.cols[rd.names[longI]][0], rd.cols[rd.names[latI]][0]];
const G = 9.81;
const laps = Analyze.identifyLaps(rd).filter(l => l.complete);
const tr = Analyze.buildTrack(rd, laps[2], origin);
const L = tr.length;
const det = Analyze.detectCorners(tr);

// Official Shanghai turns: n, dir (Wikipedia-anchored), and metadata.
const OFFICIAL = [
  {n:1,  dir:"R", type:"complex right curve"},
  {n:2,  dir:"R", type:"continues right"},
  {n:3,  dir:"R", type:"hairpin"},
  {n:4,  dir:"R", type:"exit right"},
  {n:5,  dir:"R", type:"fast right after straight"},
  {n:6,  dir:"R", type:"2nd-gear hairpin"},
  {n:7,  dir:"L", type:"left of high-speed chicane"},
  {n:8,  dir:"R", type:"right of high-speed chicane"},
  {n:9,  dir:"L", type:"slow left"},
  {n:10, dir:"L", type:"slow left"},
  {n:11, dir:"L", type:"left of slow chicane"},
  {n:12, dir:"R", type:"right of slow chicane"},
  {n:13, dir:"R", type:"long right, leads to straight"},
  {n:14, dir:"R", type:"tight hairpin end of straight"},
  {n:15, dir:"R", type:"fast right"},
  {n:16, dir:"L", type:"last left, onto pit straight"}
];

// Order-preserving direction-aware assignment:
// each detected region may cover one or more OFFICIAL turns. A region begins at the
// earliest official turn it can match (direction must match), and continues to absorb
// subsequent official turns of the SAME direction until the next region picks up.
function snap(official, regions) {
  const out = [];
  let ri = 0;
  for (let oi = 0; oi < official.length; oi++) {
    const o = official[oi];
    let r = null;
    // If this turn direction matches the current region, assign it here.
    if (ri < regions.length && regions[ri].dir === o.dir) {
      r = regions[ri];
      // Advance region if the next region has a DIFFERENT dir (current is single-turn),
      // or if the NEXT turn's dir differs (current region exhausted its run).
      const nextR = regions[ri + 1];
      const nextO = official[oi + 1];
      if (nextO && nextO.dir !== o.dir) ri++;
      else if (nextR && nextR.dir !== o.dir) ri++;
      else if (!nextO) ri++;
    }
    out.push({ o, r });
  }
  return out;
}

const m = snap(OFFICIAL, det);
console.log("direction-aware order-preserving snap:");
m.forEach(x => {
  const r = x.r;
  console.log("  T" + String(x.o.n).padStart(2) + " " + x.o.dir + " (" + x.o.type + ") -> " +
    (r ? "region@" + r.apexD.toFixed(0) + "m " + r.dir : "(no region / inside complex)"));
});

// Tabulate detected->official coverage for the fast lap to read off the mapping table.
console.log("\nDetected regions and the official turn each maps to (by order):");
let oi = 0;
det.forEach((r, di) => {
  // collect official turns this region covers
  let covered = [];
  for (let j = 0; j < OFFICIAL.length; j++) {
    if (m[j] && m[j].r === r) covered.push(OFFICIAL[j].n);
  }
  console.log("  region@" + r.apexD.toFixed(0) + "m " + r.dir + "  peak=" + r.peakLat.toFixed(2) + "g minV=" + r.minV.toFixed(0) +
    "  => official T" + (covered.join(" & ") || "?"));
});
