const Analyze = require(path.join(__dirname, "analyze.js"));
function load(p) { return Vbo.loadVboText(fs.readFileSync(p, "utf8")); }
const rd = load("dump/CLR_F296_#5204_SIC TEST0003.vbo");
const latI = Analyze.colIndex(rd, ["lat", "latitude"]);
const longI = Analyze.colIndex(rd, ["long", "longitude"]);
const origin = [rd.cols[rd.names[longI]][0], rd.cols[rd.names[latI]][0]];
const G = 9.81;
const laps = Analyze.identifyLaps(rd).filter(l => l.complete);

// Official model with FRACTIONS. Validate on each full lap that each official turn
// lands on a region of the CORRECT direction with |latAcc| above the detection threshold.
const OFF = [
  {n:1,d:0.047,dir:"R"},{n:2,d:0.119,dir:"R"},{n:3,d:0.120,dir:"R"},{n:4,d:0.170,dir:"R"},
  {n:5,d:0.213,dir:"R"},{n:6,d:0.268,dir:"R"},{n:7,d:0.338,dir:"L"},{n:8,d:0.397,dir:"R"},
  {n:9,d:0.421,dir:"L"},{n:10,d:0.468,dir:"L"},{n:11,d:0.538,dir:"L"},{n:12,d:0.548,dir:"R"},
  {n:13,d:0.628,dir:"R"},{n:14,d:0.839,dir:"R"},{n:15,d:0.874,dir:"R"},{n:16,d:0.917,dir:"L"}
];
function idxAt(tr,d){let lo=0,hi=tr.count-1;while(lo<hi){const m=(lo+hi)>>1;if(tr.dist[m]<d)lo=m+1;else hi=m;}return lo;}
function snapDir(tr, d){
  const i = idxAt(tr, d);
  // average |latAcc| over +-30m and its sign
  let s=0,c=0;
  for(let j=Math.max(0,i-15);j<Math.min(tr.count,i+15);j++){ if(isFinite(tr.latAcc[j])){s+=tr.latAcc[j];c++;} }
  const avg = c?s/c:0;
  return { g: Math.abs(avg)/G, dir: avg>=0?"R":"L" };
}

laps.forEach((lap, li) => {
  const tr = Analyze.buildTrack(rd, lap, origin);
  const L = tr.length;
  let ok=0, wrongDir=0, straight=0;
  console.log("lap " + lap.number + " len=" + L.toFixed(0) + "m");
  OFF.forEach(o=>{
    const sn = snapDir(tr, o.d*L);
    const out = "  T" + String(o.n).padStart(2) + " @" + (o.d*L).toFixed(0) + "m expect=" + o.dir + " got=" + sn.dir + " g=" + sn.g.toFixed(2) +
      (sn.dir===o.dir?"":"  <-- WRONG DIR") + (sn.g<0.30?"  <-- STRAIGHT": "");
    console.log(out);
    if(sn.dir===o.dir) ok++; else if(sn.g<0.30) straight++; else wrongDir++;
  });
  console.log("   -> correctDir=" + ok + "/16");
});
