  // ---- circuit auto-detection + official corner map ------------------------
  // Identify a known circuit from its GPS origin (VBOX arc-minute [long,lat]) plus,
  // as a guard, the measured lap length. Returns the track id or "".
  function detectCircuit(origin, lapLenM) {
    if (!origin || !isFinite(origin[0]) || !isFinite(origin[1])) return "";
    for (var id in KNOWN_TRACKS) {
      var t = KNOWN_TRACKS[id];
      if (!t.origin) continue;
      // Distance in metres between the lap origin and the circuit reference.
      var dLon = (origin[0] - t.origin[0]) * METRES_PER_ARCMIN *
                 Math.cos(t.origin[1] / 60.0 * Math.PI / 180.0);
      var dLat = (origin[1] - t.origin[1]) * METRES_PER_ARCMIN;
      var d = Math.hypot(dLon, dLat);
      // Accept only a close match; also require the lap length to be within ~±7% of
      // the published circuit length (a strong disambiguator and a guard against a
      // false positive on a short test loop that happens to start nearby).
      var lenOk = !isFinite(lapLenM) || !t.lenKm ||
                  Math.abs(lapLenM / 1000 - t.lenKm) / t.lenKm < 0.07;
      if (lenOk && d < 600) return id;
    }
    return "";
  }

  // Official corner map for a circuit, giving each published turn its position along
  // the lap (fraction of lap length). Returns [] when the circuit has no map.
  function officialCorners(trackId) {
    var t = KNOWN_TRACKS[trackId];
    return (t && t.official) ? t.official.slice() : [];
  }

  // Anchor the corner analysis to the official turn map. For circuits we know, the
  // COUNT and each turn's POSITION + DIRECTION come from the published map (which is
  // correct even where the lateral-G signal can't split same-direction turns). We keep
  // the data-driven speed / braking / exit landmarks by reading the interpolated track
  // at each official turn's position, so every reported corner carries real numbers.
  // When `trackId` is unknown or has no map, fall back to the heuristic `detected`.
  function anchoredCorners(track, trackId, detected) {
    var official = officialCorners(trackId);
    if (!official.length || !track) return detected || [];
    var L = track.length;
    function at(d) {
      // nearest sample index for distance d
      var lo = 0, hi = track.count - 1;
      while (lo < hi) { var m = (lo + hi) >> 1; if (track.dist[m] < d) lo = m + 1; else hi = m; }
      return lo;
    }
    var out = [];
    for (var i = 0; i < official.length; i++) {
      var o = official[i];
      var apexD = o.frac * L;
      var ai = at(apexD);
      var minV = isFinite(track.velMs[ai]) ? track.velMs[ai] * 3.6 : NaN;
      // Small ±span (only for entry/exit/brake context; apex position is authoritative).
      var span = 30; // metres
      function near(d0) { return at(d0); }
      var ia = near(apexD - span), ib = near(apexD + span);
      var entryV = isFinite(track.velMs[ia]) ? track.velMs[ia] * 3.6 : NaN;
      var exitV = isFinite(track.velMs[ib]) ? track.velMs[ib] * 3.6 : NaN;
      // Braking point: max speed within ~120 m before the apex.
      var brkI = ai, bestV = -Infinity;
      for (var b = Math.max(0, near(apexD - 120)); b <= ai; b++) {
        if (isFinite(track.velMs[b]) && track.velMs[b] > bestV) { bestV = track.velMs[b]; brkI = b; }
      }
      var brakeD = isFinite(track.dist[brkI]) ? track.dist[brkI] : apexD;
      out.push({
        num: o.n, dir: o.dir,
        startD: apexD - span, apexD: apexD, endD: apexD + span,
        brakd: brakeD, thrD: apexD + span,
        entryV: Math.round(entryV), minV: Math.round(minV), exitV: Math.round(exitV),
        peakLat: detected && detected[0] ? null : null,
        brakeZoneM: Math.max(0, apexD - brakeD),
        official: true
      });
    }
    return out;
  }

