const path = require("path");
global.window = global;
const Vbo = require(path.join(__dirname, "vbo.js"));
const Analyze = require(path.join(__dirname, "analyze.js"));

// Reproduce makeDemo's loop geometry to measure the actual lap length the app sees,
// and confirm the length guard rejects it for Shanghai (so the demo uses the heuristic path).
function toXy(u) {
  var x = 400 * Math.cos(u * 2 * Math.PI) + 120 * Math.cos(u * 2 * Math.PI * 3);
  var y = 250 * Math.sin(u * 2 * Math.PI) + 90 * Math.sin(u * 2 * Math.PI * 2);
  return [x, y];
}
// Measure loop length by summing segment distances around the full loop.
let len = 0, prev = null;
const N = 2000;
for (let i = 0; i <= N; i++) {
  const p = toXy(i / N);
  if (prev) len += Math.hypot(p[0] - prev[0], p[1] - prev[1]);
  prev = p;
}
console.log("demo loop length ~ " + len.toFixed(0) + "m");
console.log("detectCircuit(demoOrigin, " + len.toFixed(0) + ") = '" + Analyze.detectCircuit([-7273.3, 1880.2], len) + "'  (expect empty => heuristic path)");
console.log("Shanghai lenKm=5.451, so " + len.toFixed(0) + "m is " + (len/1000).toFixed(2) + "km — outside ±7% band? " + (Math.abs(len/1000 - 5.451)/5.451 > 0.07));
