  // Choose the fastest COMPLETE lap for a source and auto-select it (both in the player
  // scrubber and, on the analysis page, the lap selector for that source). Returns index.
  function bestLapIndex(laps) {
    if (!laps || !laps.length) return -1;
    var best = -1, bestT = Infinity;
    for (var i = 0; i < laps.length; i++) {
      var l = laps[i];
      if (!l.complete || !isFinite(l.lap_s)) continue;
      if (l.lap_s < bestT) { bestT = l.lap_s; best = i; }
    }
    if (best >= 0) return best;
    // fall back to shortest lap time overall
    for (var i = 0; i < laps.length; i++) {
      if (isFinite(laps[i].lap_s) && laps[i].lap_s < bestT) { bestT = laps[i].lap_s; best = i; }
