{"content":"// diag_videocut.js -- verify the onboard-video auto-cut logic on a real .vbo.
//   * Finds the best (fastest) complete lap.
//   * Selects the correct video-time channel (must pick `avitime`, NOT `avifileindex`,
//     which is a constant per-file index and would shadow it by column order).
//   * Normalises the channel to seconds (Racelogic `avitime` is in ms) and computes the
//     [start,end] cut window for the best lap.
const fs = require("fs");
const path = require("path");
global.window = global;
const Vbo = require(path.join(__dirname, "vbo.js"));
const Analyze = require(path.join(__dirname, "analyze.js"));
function load(p) { return Vbo.loadVboText(fs.readFileSync(p, "utf8")); }
function fmtTime(s){ if(!isFinite(s))return "—"; var m=Math.floor(s/60),sec=s-m*60; return m+":"+(sec<10?"0":"")+sec.toFixed(2); }

const rd = load("dump/CLR_F296_#5204_SIC TEST0003.vbo");
const laps = Analyze.identifyLaps(rd).filter(l => l.complete);

let best=-1, bestT=Infinity;
laps.forEach((l,i)=>{ if(l.complete && isFinite(l.lap_s) && l.lap_s<bestT){bestT=l.lap_s;best=i;} });
console.log("best lap index=" + best + "  Lap " + laps[best].number + "  time=" + fmtTime(laps[best].lap_s));
const lap = laps[best];

// channel must prefer avitime/avisynctime (time-bearing) over avifileindex
let idx = Analyze.colIndex(rd, ["avitime","avisynctime","avindex"]);
if (idx < 0) idx = Analyze.colIndex(rd, ["avifileindex"]);
const col = rd.cols[rd.names[idx]];
console.log("video-time channel column#" + idx + " '" + rd.names[idx] + "' (avifileindex col#=" + Analyze.colIndex(rd,["avifileindex"]) + " should differ)");

// rate detection (ms -> s) then build map in seconds, mirroring app.js rebuildVideoMap
const time = rd.time_ns;
const diffs=[];
for(let i=lap.startRow+1;i<Math.min(lap.endRow,col.length);i++){const dv=col[i]-col[i-1],dt=(time[i]-time[i-1])/1e9; if(isFinite(dv)&&isFinite(dt)&&dt>0&&dv>0&&dv<1e6)diffs.push(dv/dt);}
diffs.sort((a,b)=>a-b); const rate=diffs[Math.floor(diffs.length/2)]; const vscale=rate>=1?rate:1;
const m=[]; let minVt=Infinity,maxVt=-Infinity;
for(let i=lap.startRow;i<Math.min(lap.endRow,col.length);i++){const t=(time[i]-time[lap.startRow])/1e9;const vt=col[i]/vscale; if(isFinite(vt)){m.push([t,vt]); if(vt<minVt)minVt=vt; if(vt>maxVt)maxVt=vt;}}
const useMap = m.length && (maxVt-minVt)>0.5;
console.log("rate=" + rate + " ticks/sec  map samples=" + m.length + "  usable=" + useMap);
if (useMap) {
  const seg = { start: m[0][1], end: m[m.length-1][1] };
  console.log("AUTO-CUT segment: video " + seg.start.toFixed(2) + "s -> " + seg.end.toFixed(2) + "s  (length " + (seg.end-seg.start).toFixed(2) + "s)");
  console.log("lap_s=" + lap.lap_s.toFixed(2) + "s  match=" + (Math.abs((seg.end-seg.start)-lap.lap_s)<2));
} else {
  console.log("channel does not span time -> will NOT auto-cut");
}
