{"code":"async (page) => {
  return await page.evaluate(() => {
    // Build a minimal valid .vbo with a few laps + an avitime channel (ms).
    const short = ["sats","time","lat","long","velocity","heading","height","vert-vel",
      "Tsample","solution_type","avifileindex","avitime",
      "aps_fer","pbrake_f_fer","steer_fer","nmot","gear","Lap_Number"];
    const dt = 0.1;
    function gen(laps, base) {
      const rows = [];
      let gIdx = 0;
      const origLat = 1880.2, origLong = -7273.3;
      for (let L = 0; L < laps; L++) {
        const t0 = 30000.0 + L * 600; // 600s per lap
        const n = 1600;
        for (let i = 0; i < n; i++) {
          const u = i / n, phase = u * 4 * Math.PI;
          const v = (150 + 110 * Math.abs(Math.sin(phase))) * base;
          const x = 400 * Math.cos(u*2*Math.PI) + 120*Math.cos(u*2*Math.PI*3);
          const y = 250 * Math.sin(u*2*Math.PI) + 90*Math.sin(u*2*Math.PI*2);
          const lat = origLat + y/1852.0;
          const long = origLong + x/(1852.0*Math.cos(origLat*Math.PI/10800));
          const t = t0 + i*dt;
          const sec = (t % 86400 + 86400) % 86400;
          const hh = Math.floor(sec/3600), mm = Math.floor((sec%3600)/60), ss = sec%60;
          const hhmmss = hh*10000 + mm*100 + ss;
          // avitime advances ~1000/s (ms)
          const avitime = (t - 30000.0) * 1000;
          rows.push("8 " + hhmmss.toFixed(1) + " " + lat.toFixed(6) + " " + long.toFixed(6) + " " +
            v.toFixed(1) + " " + (Math.atan2(y,x)*180/Math.PI+360+90)%360 + " 100.00 -0.01 " + dt.toFixed(3) +
            " 1 " + L + " " + avitime.toFixed(0) + " " + Math.max(0,Math.min(100,75-45*Math.abs(Math.sin(phase)))).toFixed(1) +
            " " + (v>225?50:0) + " " + (35*Math.sin(phase)).toFixed(1) + " " + Math.round(3000+v*36) + " " +
            Math.min(6,Math.max(1,Math.round(v/45))) + " " + (L+1));
          gIdx++;
        }
      }
      return "File created on 01/01/2026 @ 12:00:00\n\n[header]\n" +
        ["satellites","time","latitude","longitude","velocity kmh","heading","height","vertical velocity m/s",
         "sampleperiod","solution type","avifileindex","avitime","aps_fer","pbrake_f_fer","steer_fer","nmot","gear","Lap_Number"].join("\n") +
        "\n[channel units]\ns % bar deg rpm\n[AVI]\ndemo_\nmp4\n\n[column names]\n" + short.join(" ") +
        "\n[data]\n" + rows.join("\n") + "\n";
    }
    const refText = gen(3, 1.0);
    const tgtText = gen(3, 0.93);
    const vid = new Blob(["fake"], { type: "video/mp4" });
    return Store.saveSession({
      ref: { name: "driverA.vbo", text: refText },
      tgt: { name: "driverB.vbo", text: tgtText },
      refVideo: { name: "A.mp4", blob: vid }, tgtVideo: { name: "B.mp4", blob: vid }
    }).then(() => ({ saved: true, refLen: refText.length, tgtLen: tgtText.length }));
  });
}"}

